n = int(input())
for i in range(n):
    m = int(input())
    p = []
    for k in range(m):
        p.append(int(input()))
    at = int(input())
    degree = -1
    value = 0
    for k in range(m):
        if p[k] != 0:
            degree = k
        value = value + p[k] * at**k
    if degree == -1:
        print(f"degree none, leading none, p({at}) = {value}")
    else:
        print(f"degree {degree}, leading {p[degree]}, p({at}) = {value}")

def read_list():
    m = int(input())
    p = []
    for k in range(m):
        p.append(int(input()))
    return p

def multiply(a, b):
    c = [0] * (len(a) + len(b) - 1)
    for i in range(len(a)):
        for j in range(len(b)):
            c[i + j] = c[i + j] + a[i] * b[j]
    return c

n = int(input())
for i in range(n):
    a = read_list()
    b = read_list()
    c = multiply(a, b)
    print(f"product: {c}")
    print(f"degree: {len(c) - 1}")
